CREATE TABLE users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL, course TEXT NOT NULL, teacher_id INTEGER REFERENCES users(id), salt TEXT NOT NULL, password TEXT NOT NULL, photo TEXT NOT NULL DEFAULT '');
CREATE TABLE lessons(id INTEGER PRIMARY KEY AUTOINCREMENT, subject TEXT NOT NULL, title TEXT NOT NULL, objective TEXT NOT NULL, explanation TEXT NOT NULL, example TEXT NOT NULL, status TEXT NOT NULL, origin TEXT NOT NULL);
CREATE TABLE questions(id INTEGER PRIMARY KEY AUTOINCREMENT, lesson_id INTEGER NOT NULL REFERENCES lessons(id), prompt TEXT NOT NULL, a TEXT NOT NULL, b TEXT NOT NULL, c TEXT NOT NULL, correct INTEGER NOT NULL CHECK(correct BETWEEN 0 AND 2), explanation TEXT NOT NULL, final_test INTEGER NOT NULL);
CREATE TABLE assignments(student_id INTEGER REFERENCES users(id), lesson_id INTEGER REFERENCES lessons(id), max_attempts INTEGER NOT NULL CHECK(max_attempts BETWEEN 1 AND 5), start_date TEXT NOT NULL, end_date TEXT NOT NULL, PRIMARY KEY(student_id,lesson_id));
CREATE TABLE practice(student_id INTEGER REFERENCES users(id), question_id INTEGER REFERENCES questions(id), choice INTEGER NOT NULL, correct INTEGER NOT NULL, date TEXT NOT NULL, PRIMARY KEY(student_id,question_id));
CREATE TABLE attempts(id INTEGER PRIMARY KEY AUTOINCREMENT, student_id INTEGER REFERENCES users(id), lesson_id INTEGER REFERENCES lessons(id), number INTEGER NOT NULL, score INTEGER NOT NULL, total INTEGER NOT NULL, date TEXT NOT NULL, UNIQUE(student_id,lesson_id,number));
CREATE TABLE test_answers(attempt_id INTEGER REFERENCES attempts(id), question_id INTEGER REFERENCES questions(id), choice INTEGER NOT NULL, correct INTEGER NOT NULL, PRIMARY KEY(attempt_id,question_id));
CREATE TABLE notes(student_id INTEGER REFERENCES users(id), lesson_id INTEGER REFERENCES lessons(id), note TEXT NOT NULL, validated INTEGER NOT NULL, PRIMARY KEY(student_id,lesson_id));
CREATE TABLE audit(id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL);
